using SchoolERP.Application.Features.Houses;using SchoolERP.Domain.Entities;using SchoolERP.Domain.Enums;using SchoolERP.Domain.Exceptions;using SchoolERP.Domain.Interfaces;using Xunit;namespace SchoolERP.UnitTests;
public sealed class HouseManagementTests{
 [Fact]public void Create_sets_ownership_draft_and_normalizes(){var t=Guid.NewGuid();var s=Guid.NewGuid();var x=House.Create(t,s," Red House "," red ","Red","#ef4444",0,"Unity",null);Assert.Equal((t,s),(x.TenantId,x.SchoolId));Assert.Equal("RED",x.Code);Assert.Equal("#EF4444",x.ColorHex);Assert.Equal(HouseStatus.Draft,x.Status);Assert.Equal(0,x.DisplayOrder);Assert.IsAssignableFrom<ITenantEntity>(x);}
 [Theory][InlineData("#FF0000","#FF0000")][InlineData("#abcdef","#ABCDEF")]public void Valid_colors_are_normalized(string value,string expected)=>Assert.Equal(expected,House.NormalizeColor(value));
 [Theory][InlineData("red")][InlineData("#FFF")][InlineData("#GG0000")][InlineData("rgb(1,2,3)")]public void Invalid_colors_are_rejected(string value)=>Assert.Throws<DomainException>(()=>House.NormalizeColor(value));
 [Theory][InlineData("A B")][InlineData("A@B")][InlineData("")]public void Invalid_codes_are_rejected(string value)=>Assert.Throws<DomainException>(()=>House.NormalizeCode(value));
 [Fact]public void Negative_order_is_rejected()=>Assert.Throws<DomainException>(()=>House.Create(Guid.NewGuid(),Guid.NewGuid(),"X","X",null,"#000000",-1));
 [Fact]public void Lifecycle_and_archived_read_only_are_enforced(){var x=House.Create(Guid.NewGuid(),Guid.NewGuid(),"X","X",null,"#000000",0);x.Activate(DateTime.UtcNow);Assert.Throws<InvalidHouseStatusTransitionException>(()=>x.Archive(DateTime.UtcNow));x.Deactivate(DateTime.UtcNow);x.Archive(DateTime.UtcNow);Assert.Throws<HouseArchivedReadOnlyException>(()=>x.UpdateDetails("Y",null,"#FFFFFF",0,null,null,DateTime.UtcNow));}
 [Fact]public void Requests_do_not_accept_ownership_or_status(){var create=typeof(CreateHouseRequest).GetProperties().Select(x=>x.Name);Assert.DoesNotContain("TenantId",create);Assert.DoesNotContain("SchoolId",create);Assert.DoesNotContain("Status",create);var update=typeof(UpdateHouseRequest).GetProperties().Select(x=>x.Name);Assert.DoesNotContain("Code",update);Assert.DoesNotContain("Status",update);}
}
